  "向 {0} 导入 {1} 条命令（合并 {2} 条重复行）？ {3} 相同命令码更新名称并保留已绑定功能；新命令需在工作区绑定功能。": { "en": "Import {1} commands into {0} (merge {2} duplicate rows)? {3} Existing command codes will have their names updated and keep their bound functions; bind new commands in the workspace.", "id": "Impor {1} perintah ke {0} (gabungkan {2} baris duplikat)? {3} Nama kode yang ada diperbarui dan fungsi terikat dipertahankan; ikat perintah baru di ruang kerja.", "vi": "Nhập {1} lệnh vào {0} (gộp {2} hàng trùng)? {3} Mã đã có sẽ được cập nhật tên và giữ chức năng đã gán; hãy gán chức năng cho lệnh mới trong vùng làm việc.", "th": "นำเข้า {1} คำสั่งไปยัง {0} (รวมแถวซ้ำ {2} แถว)? {3} รหัสเดิมจะอัปเดตชื่อและคงฟังก์ชันที่ผูกไว้ โปรดผูกฟังก์ชันให้คำสั่งใหม่ในพื้นที่ทำงาน" },
