  "自定义分辨率宽度必须为320至4088的8倍数，高度为240至2160，刷新率为24至60Hz整数": { "en": "Custom resolution width must be a multiple of 8 from 320 to 4088, height 240 to 2160, and refresh rate an integer from 24 to 60 Hz", "id": "Lebar resolusi khusus harus kelipatan 8 dari 320 hingga 4088, tinggi 240 hingga 2160, dan laju penyegaran bilangan bulat 24 hingga 60 Hz", "vi": "Chiều rộng tùy chỉnh phải là bội số của 8 từ 320 đến 4088, chiều cao từ 240 đến 2160 và tần số quét là số nguyên từ 24 đến 60 Hz", "th": "ความกว้างแบบกำหนดเองต้องเป็นพหุคูณของ 8 ตั้งแต่ 320 ถึง 4088 ความสูง 240 ถึง 2160 และอัตรารีเฟรชเป็นจำนวนเต็ม 24 ถึง 60 Hz" },
